package com.bank.striped;

public class StripedRegister {

    public RegisterNode reverseAlternate(RegisterNode head, int k) {
        if (head == null || k < 2) return head;
        RegisterNode dummy = new RegisterNode(-1);
        dummy.next = head;
        RegisterNode previousTail = dummy;

        while (previousTail != null && previousTail.next != null) {
            // Ensure a full group of k remains to reverse.
            RegisterNode check = previousTail;
            for (int i = 0; i < k && check != null; i++) check = check.next;
            if (check == null) break;

            RegisterNode groupFirst = previousTail.next;   // becomes group tail
            RegisterNode previous = null, current = groupFirst;
            for (int i = 0; i < k; i++) {                  // reverse k nodes
                RegisterNode next = current.next;
                current.next = previous;
                previous = current;
                current = next;
            }
            previousTail.next = previous;    // link reversed group
            groupFirst.next = current;
            previousTail = groupFirst;       // now at tail of reversed group

            // SKIP the next k nodes (leave them in order).
            for (int i = 0; i < k && previousTail != null; i++) previousTail = previousTail.next;
        }
        return dummy.next;
    }
}
