package com.bank.striped;

import java.util.logging.Logger;

public class AlternateDemo {
    private static final Logger log = Logger.getLogger(AlternateDemo.class.getName());

    public static void main(String[] args) {
        RegisterNode head = build(new int[]{1, 2, 3, 4, 5, 6, 7, 8});
        log.info("Original: " + render(head));

        RegisterNode out = new StripedRegister().reverseAlternate(head, 2);
        log.info("Alternating reverse k=2: " + render(out));
    }

    static RegisterNode build(int[] ids) {
        RegisterNode d = new RegisterNode(-1), t = d;
        for (int id : ids) { t.next = new RegisterNode(id); t = t.next; }
        return d.next;
    }

    static String render(RegisterNode n) {
        StringBuilder sb = new StringBuilder();
        while (n != null) { sb.append(n.id); if (n.next != null) sb.append(" -> "); n = n.next; }
        return sb.append(" -> null").toString();
    }
}
